const durontoServices=[{name:"Sealdah - Bikaner Duronto Express",origin:"Sealdah",destination:"Bikaner",majorStations:["Dhanbad","Kanpur Central","New Delhi","Jaipur"],description:"One of the prominent Duronto services connecting Eastern India to Rajasthan."},{name:"Mumbai CSMT - Howrah Duronto Express",origin:"Mumbai CSMT",destination:"Howrah",majorStations:["Bhusaval","Nagpur","Raipur","Tatanagar"],description:"A crucial high-speed link between the financial capital and the cultural capital."},{name:"Yesvantpur - Delhi Sarai Rohilla Duronto Express",origin:"Yesvantpur",destination:"Delhi Sarai Rohilla",majorStations:["Secunderabad","Balharshah","Jhansi"],description:"A fast connection bridging South India and the National Capital."},{name:"Pune - Hazrat Nizamuddin Duronto Express",origin:"Pune",destination:"Hazrat Nizamuddin",majorStations:["Lonavala","Vasai Road","Vadodara","Ratlam","Kota"],description:"A premier service linking Pune with New Delhi efficiently."}],routes=[{origin:"Sealdah",destination:"New Delhi",importantStations:["Dhanbad","Kanpur Central"],regions:["West Bengal","Delhi"]},{origin:"Mumbai Central",destination:"New Delhi",importantStations:["Vadodara","Ratlam","Kota"],regions:["Maharashtra","Delhi"]},{origin:"Chennai Central",destination:"Hazrat Nizamuddin",importantStations:["Vijayawada","Balharshah","Jhansi"],regions:["Tamil Nadu","Delhi"]},{origin:"Ernakulam",destination:"Lokmanya Tilak Terminus",importantStations:["Kozhikode","Mangaluru","Madgaon","Ratnagiri"],regions:["Kerala","Maharashtra"]}];function renderServices(){const a=document.getElementById("services-container");a&&(a.innerHTML=durontoServices.map(a=>`\n    <div class="card">\n      <i class="fa-solid fa-train icon-feature"></i>\n      <h3>${a.name}</h3>\n      <p style="margin-bottom: 10px;"><strong>${a.origin} <i class="fa-solid fa-arrow-right"></i> ${a.destination}</strong></p>\n      <p style="font-size: 0.9rem; color: #ccc;"><strong>Major Stations:</strong> ${a.majorStations.join(", ")}</p>\n      <p style="margin-top: 10px;">${a.description}</p>\n    </div>\n  `).join(""))}function renderRoutes(){const a=document.getElementById("routes-container");a&&(a.innerHTML=routes.map(a=>`\n    <div class="route-card">\n      <div>\n        <div class="origin-dest">${a.origin} <i class="fa-solid fa-arrow-right" style="color: var(--duronto-yellow); margin: 0 10px;"></i> ${a.destination}</div>\n        <div class="stations"><strong>Via:</strong> ${a.importantStations.join(", ")}</div>\n      </div>\n      <div>\n        <span style="background: var(--duronto-green); color: var(--duronto-bg); padding: 5px 10px; border-radius: 4px; font-size: 0.8rem; font-weight: bold;">\n          ${a.regions.join(" &middot; ")}\n        </span>\n      </div>\n    </div>\n  `).join(""))}document.addEventListener("DOMContentLoaded",()=>{renderServices(),renderRoutes()});